<script setup lang="ts">
import { LogIn,LockKeyhole,ShieldCheck,House } from 'lucide-vue-next'
definePageMeta({layout:'blank'})
const route=useRoute();const username=ref('congdan.demo');const password=ref('Demo@2026!');const loading=ref(false);const errorText=ref('')
async function login(){loading.value=true;errorText.value='';try{await $fetch('/api/auth/login',{method:'POST',body:{username:username.value,password:password.value}});await refreshNuxtData('citizen-auth');const next=String(route.query.next||'/');await navigateTo(next.startsWith('/')&&!next.startsWith('//')?next:'/')}catch(e){errorText.value=readableError(e)}finally{loading.value=false}}
</script>
<template><div class="grid min-h-screen lg:grid-cols-2"><div class="hero-gradient hero-pattern relative hidden items-center justify-center overflow-hidden p-12 text-white lg:flex"><div class="absolute inset-y-0 right-0 w-full opacity-30"><img src="/images/ubnd-hero-clean.png" class="h-full w-full object-contain object-top" alt="Trụ sở UBND minh họa"/></div><div class="relative z-10 max-w-lg"><span class="mb-6 flex h-20 w-20 items-center justify-center rounded-2xl border border-white/40 bg-white/20"><House :size="45"/></span><h1 class="text-5xl font-black">CommuneOS</h1><p class="mt-4 text-xl font-bold">Cổng dịch vụ hành chính công cấp xã</p><p class="mt-5 text-sm leading-7 text-blue-50">Nộp hồ sơ trực tuyến · Theo dõi tiến độ · Minh bạch thông tin · Bảo vệ quyền truy cập của công dân.</p></div></div><div class="flex items-center justify-center p-6"><form class="panel w-full max-w-md space-y-5 p-7" @submit.prevent="login"><div class="mb-6 text-center"><span class="mx-auto mb-3 grid h-14 w-14 place-items-center rounded-2xl bg-blue-100 text-brand-700"><LockKeyhole :size="29"/></span><h2 class="text-2xl font-black">Đăng nhập Công dân</h2><p class="mt-1 text-sm text-muted">Môi trường trình diễn với tài khoản mẫu</p></div><div class="rounded-lg border border-blue-200 bg-blue-50 p-3 text-sm text-brand-800"><b>Thông tin đăng nhập demo</b><p>Tên đăng nhập: <code>congdan.demo</code></p><p>Mật khẩu: <code>Demo@2026!</code></p><p class="mt-1 text-xs">Không sử dụng dữ liệu cá nhân thật.</p></div><div><label class="field-label">Tên đăng nhập</label><input v-model="username" class="field" required autocomplete="username"/></div><div><label class="field-label">Mật khẩu</label><input v-model="password" class="field" type="password" required autocomplete="current-password"/></div><p v-if="errorText" class="rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{{errorText}}</p><button type="submit" class="btn-primary w-full" :disabled="loading"><LogIn :size="17"/>{{loading?'Đang xác thực...':'Đăng nhập'}}</button><NuxtLink to="/" class="block text-center text-sm font-semibold text-brand-700">Quay về trang chủ</NuxtLink><p class="flex items-start gap-1.5 text-xs leading-5 text-muted"><ShieldCheck :size="20" class="shrink-0"/>Tài khoản demo được kiểm tra trên máy chủ. Đăng nhập OIDC/Keycloak sẽ được tích hợp ở giai đoạn lõi.</p></form></div></div></template>
